const valueRanges = $input.first()?.json?.valueRanges || [];
const MAX_CAPACITY_DEFAULT = 16;

function cleanText(str) {
  if (str === undefined || str === null) return '';
  return String(str).replace(/\\+n/g, '\n').trim();
}
function safeText(str, fallback = '-') {
  const cleaned = cleanText(str);
  return (cleaned && cleaned.length > 0) ? cleaned : fallback;
}

const todayStr = new Date().toLocaleDateString('zh-TW', {
  timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit'
}).replace(/\//g, '');

const sessions = valueRanges.map(vr => {
  const dateMatch = vr.range.match(/(\d{8})/);
  const date = dateMatch ? dateMatch[1] : "";

  const rawValues = vr.values || [];

  // 前 14 列是「標題/內容」基本資訊區(D欄=標題,E欄=內容,對應 C1:E50 抓回來後 D是index1,E是index2)
  const info = {};
  rawValues.slice(0, 14).forEach(row => {
    const title = row[1] ? String(row[1]).trim() : '';   // D欄
    const content = row[2] !== undefined ? String(row[2]).trim() : '';  // E欄
    if (title) info[title] = content;
  });

  // 第 16 列(index 15)以後才是報名名單
  const validNames = rawValues.slice(15)
    .flat()
    .map(n => (typeof n === 'string' ? n.trim() : ''))
    .filter(n => n.length > 0);

  const capacity = Number(info['人數']) || MAX_CAPACITY_DEFAULT;
  const count = validNames.length;
  const remaining = Math.max(0, capacity - count);

  return { date, validNames, count, remaining, info, capacity };
})
.filter(s => s.date.length === 8 && s.date >= todayStr);

sessions.sort((a, b) => a.date.localeCompare(b.date));

const bubbles = sessions.map(session => {
  const { date, validNames, count, remaining, info } = session;

  let formattedDate = date;
  if (/^\d{8}$/.test(date)) {
    const y = parseInt(date.slice(0, 4), 10);
    const m = parseInt(date.slice(4, 6), 10) - 1;
    const d = parseInt(date.slice(6, 8), 10);
    const dateObj = new Date(y, m, d);
    const days = ['日', '一', '二', '三', '四', '五', '六'];
    formattedDate = `${date.slice(0, 4)}/${date.slice(4, 6)}/${date.slice(6, 8)} (${days[dateObj.getDay()]})`;
  }

  // 從基本資訊區抓取團名
  const groupName = safeText(info['團名'], '羽球活動團');
  const displayTitle = groupName.includes('🏸') || groupName.includes('🏓') ? groupName : `🏸 ${groupName}`;

  let memberContents = [];

  if (validNames.length === 0) {
    memberContents = [{
      "type": "text", "text": "目前尚無人報名，快搶頭香！",
      "size": "sm", "color": "#aaaaaa", "style": "italic", "align": "center"
    }];
  } else if (validNames.length <= 8) {
    // 🟢 8 人以下：單欄直向排列 (編號右對齊)
    memberContents = validNames.map((name, index) => ({
      "type": "box", "layout": "horizontal", "spacing": "xs",
      "contents": [
        { "type": "text", "text": `${index + 1}.`, "size": "md", "color": "#1DB446", "weight": "bold", "flex": 2, "align": "end" },
        { "type": "text", "text": name, "size": "md", "color": "#333333", "weight": "bold", "flex": 8, "margin": "sm" }
      ],
      "margin": "xs"
    }));
  } else {
    // 🟢 超過 8 人：自動切換為左右雙欄 (編號右對齊，小數點對齊)
    const midPoint = 8;
    const leftNames = validNames.slice(0, midPoint);
    const rightNames = validNames.slice(midPoint);

    const renderColItem = (name, index) => ({
      "type": "box", "layout": "horizontal", "spacing": "xs",
      "contents": [
        { "type": "text", "text": `${index + 1}.`, "size": "md", "color": "#1DB446", "weight": "bold", "flex": 3, "align": "end" },
        { "type": "text", "text": name, "size": "md", "color": "#333333", "weight": "bold", "flex": 7, "margin": "xs", "wrap": false }
      ],
      "margin": "xs"
    });

    const leftCol = { "type": "box", "layout": "vertical", "flex": 1, "contents": leftNames.map((name, idx) => renderColItem(name, idx)) };
    const rightCol = { "type": "box", "layout": "vertical", "flex": 1, "contents": rightNames.map((name, idx) => renderColItem(name, idx + midPoint)) };

    memberContents = [{ "type": "box", "layout": "horizontal", "spacing": "md", "contents": [leftCol, rightCol] }];
  }

  return {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box",
      "layout": "vertical",
      "backgroundColor": "#1DB446",
      "paddingAll": "xl",
      "contents": [
        { "type": "text", "text": displayTitle, "weight": "bold", "color": "#FFFFFF", "size": "xl", "wrap": true, "maxLines": 1 },
        { "type": "text", "text": `📅 場次日期：${formattedDate}`, "size": "sm", "weight": "bold", "color": "#FFFFFF", "margin": "xs", "maxLines": 1 }
      ]
    },
    "body": {
      "type": "box", "layout": "vertical", "paddingAll": "xl",
      "contents": [
        {
          "type": "box", "layout": "horizontal",
          "contents": [
            { "type": "text", "text": `已報名：${count} 人`, "size": "sm", "weight": "bold", "color": "#333333" },
            { "type": "text", "text": `剩餘：${remaining} 名額`, "size": "sm", "weight": "bold", "color": remaining > 0 ? "#e74c3c" : "#95a5a6", "align": "end" }
          ]
        },
        { "type": "separator", "margin": "md" },
        { "type": "box", "layout": "vertical", "margin": "md", "spacing": "xs", "contents": memberContents }
      ]
    },
    "footer": {
      "type": "box", "layout": "vertical", "paddingAll": "xl",
      "contents": [{
        "type": "button", "style": "primary", "height": "sm", "color": "#1DB446",
        "action": { "type": "postback", "label": "查看詳情", "data": `action=refresh&date=${date}`, "displayText": `查看詳情 ${date}` }
      }]
    }
  };
});

if (bubbles.length === 0) {
  bubbles.push({
    "type": "bubble", "size": "mega",
    "body": { "type": "box", "layout": "vertical",
      "contents": [{ "type": "text", "text": "🏸 目前尚無開放中的打球場次", "weight": "bold", "size": "md", "align": "center", "color": "#666666" }]
    }
  });
}

const flexCarousel = { "type": "carousel", "contents": bubbles };

return [{ json: { flexMessage: JSON.stringify(flexCarousel), totalSessions: sessions.length } }];

const allStates = $input.all().map(item => item.json);
const lineData = $('Line Messaging Trigger').first().json;
const userId = lineData.source ? lineData.source.userId : '';
const rawText = lineData.message ? lineData.message.text.trim() : '';

const EXPIRE_MS = 30000;

const validState = allStates.find(item => {
  const uid = String(item.USERID || item['USERID '] || '').trim();
  return uid === userId && uid.length > 0;
});

if (!validState) {
  return [];
}

const targetDateRaw = String(validState.TARGET_DATE || validState['TARGET_DATE ']).trim();
const timestampRaw = String(validState.TIMESTAMP || validState['TIMESTAMP ']).trim();

if (!targetDateRaw || targetDateRaw === 'N/A' || !timestampRaw) {
  return [{
    json: {
      status: 'EXPIRED',
      USERID: userId,
      row_number: validState.row_number,   // 🟢 新增這行
      replyMessage: ''
    }
  }];
}

const elapsed = Date.now() - Number(timestampRaw);
if (isNaN(elapsed) || elapsed > EXPIRE_MS) {
  return [{
    json: {
      status: 'EXPIRED',
      USERID: userId,
      targetDate: targetDateRaw,
      row_number: validState.row_number,   // 🟢 新增這行
      replyMessage: `⌛ 報名逾時，您輸入的內容未被記錄。\n如需報名請重新點選「我要報名」按鈕。`
    }
  }];
}

const names = rawText.split(/[\s,$,/,、,\n\r]+/).filter(n => n.length > 0);
const timestampStr = new Date().toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
const combinedNamesText = names.join('、');

return [{
  json: {
    status: 'CHECK_CAPACITY',
    targetDate: targetDateRaw,
    USERID: userId,
    row_number: validState.row_number,   // 🟢 新增這行
    names: names,
    totalCount: names.length,
    timestamp: timestampStr,
    replyMessage: `🎉 報名成功！\n📅 場次：${targetDateRaw}\n👤 報名名單：${combinedNamesText}\n🔢 總人數：${names.length} 位`
  }
}];

// 1. 取得目前分頁所有列資料(讀取場次人數 的輸出)
const sheetRows = $input.all().map(item => item.json);

// 2. 取得這次報名的原始資訊(從更早的節點拿,因為讀取場次人數之後這些欄位就消失了)
const bookingData = $('2. 驗證快取與解析姓名').first().json;
const targetDate = bookingData.targetDate;
const userId = bookingData.USERID;
const names = bookingData.names || [];
const requestedCount = names.length;

// 3. 計算場次上限(從「標題=人數」那一列讀取,若無則預設 16)
const capacityRow = sheetRows.find(r => r['標題'] === '人數');
const maxCapacity = capacityRow ? Number(capacityRow['內容']) || 16 : 16;

// 4. 計算目前已報名人數(編號+名字都有值才算佔用)
const bookedRows = sheetRows.filter(r => {
  const hasNumber = r['編號'] !== undefined && r['編號'] !== null && String(r['編號']).trim() !== '';
  const hasName = r['名字'] !== undefined && r['名字'] !== null && String(r['名字']).trim().length > 0;
  return hasNumber && hasName;
});
const currentBookingCount = bookedRows.length;
const remainingCount = Math.max(0, maxCapacity - currentBookingCount);

// 5. 真正判斷是否可報名
const canBook = remainingCount >= requestedCount && requestedCount > 0;

if (!canBook) {
  // ---- 報名失敗:組真實數字的卡片 ----
  let formattedDate = targetDate;
  if (/^\d{8}$/.test(targetDate)) {
    const y = parseInt(targetDate.slice(0, 4), 10);
    const m = parseInt(targetDate.slice(4, 6), 10) - 1;
    const d = parseInt(targetDate.slice(6, 8), 10);
    const dateObj = new Date(y, m, d);
    const days = ['日', '一', '二', '三', '四', '五', '六'];
    formattedDate = `${targetDate.slice(0, 4)}/${targetDate.slice(4, 6)}/${targetDate.slice(6, 8)} (${days[dateObj.getDay()]})`;
  }

  const flexFailPrompt = {
    "type": "bubble",
    "size": "mega",
    "header": {
      "type": "box", "layout": "vertical", "backgroundColor": "#E74C3C", "paddingAll": "xl",
      "contents": [
        { "type": "text", "text": "⚠️ 報名失敗", "weight": "bold", "color": "#FFFFFF", "size": "xl", "wrap": true },
        { "type": "text", "text": `📅 場次日期：${formattedDate}`, "size": "sm", "weight": "bold", "color": "#FFFFFF", "margin": "xs" }
      ]
    },
    "body": {
      "type": "box", "layout": "vertical", "spacing": "md", "paddingAll": "xl",
      "contents": [
        { "type": "text", "text": "非常抱歉，您欲報名的人數已超過該場次剩餘名額！", "size": "sm", "color": "#333333", "wrap": true, "weight": "bold" },
        { "type": "separator", "margin": "md" },
        {
          "type": "box", "layout": "vertical", "spacing": "sm", "margin": "md",
          "contents": [
            { "type": "box", "layout": "horizontal", "contents": [
              { "type": "text", "text": "場次上限", "size": "sm", "color": "#888888", "flex": 3 },
              { "type": "text", "text": `${maxCapacity} 人`, "size": "sm", "color": "#333333", "weight": "bold", "flex": 5 }
            ]},
            { "type": "box", "layout": "horizontal", "contents": [
              { "type": "text", "text": "目前已報名", "size": "sm", "color": "#888888", "flex": 3 },
              { "type": "text", "text": `${currentBookingCount} 人`, "size": "sm", "color": "#333333", "weight": "bold", "flex": 5 }
            ]},
            { "type": "box", "layout": "horizontal", "contents": [
              { "type": "text", "text": "您欲報名", "size": "sm", "color": "#888888", "flex": 3 },
              { "type": "text", "text": `${requestedCount} 人`, "size": "sm", "color": "#E74C3C", "weight": "bold", "flex": 5 }
            ]},
            { "type": "box", "layout": "horizontal", "contents": [
              { "type": "text", "text": "剩餘名額", "size": "sm", "color": "#888888", "flex": 3 },
              { "type": "text", "text": `${remainingCount} 人`, "size": "sm", "color": "#27AE60", "weight": "bold", "flex": 5 }
            ]}
          ]
        },
        {
          "type": "box", "layout": "vertical", "margin": "lg", "paddingAll": "md",
          "backgroundColor": "#FDEDEC", "cornerRadius": "md",
          "contents": [
            { "type": "text", "text": "💡 提示：", "weight": "bold", "size": "xs", "color": "#E74C3C" },
            { "type": "text", "text": `建議減少報名人數（至多 ${remainingCount} 位）或重新點選頁面查看最新名單。`, "size": "xs", "color": "#C0392B", "margin": "xs", "wrap": true }
          ]
        }
      ]
    },
    "footer": {
      "type": "box", "layout": "vertical", "paddingAll": "xl",
      "contents": [{
        "type": "button", "style": "primary", "color": "#E74C3C", "height": "sm",
        "action": { "type": "postback", "label": "刷新報名頁面", "data": `action=refresh&date=${targetDate}`, "displayText": "刷新頁面" }
      }]
    }
  };

  return [{ json: { canBook: false, flexMessage: JSON.stringify(flexFailPrompt) } }];
}

// ---- 報名成功:把姓名分配到空的 row_number 上,準備寫入 ----
// 找出所有「有編號但沒有名字」的空位(1~maxCapacity)
const emptySlots = sheetRows.filter(r => {
  const hasNumber = r['編號'] !== undefined && r['編號'] !== null && String(r['編號']).trim() !== '';
  const noName = !r['名字'] || String(r['名字']).trim() === '';
  return hasNumber && noName;
}).sort((a, b) => Number(a['編號']) - Number(b['編號']));

const rowsToWrite = names.map((name, idx) => {
  const slot = emptySlots[idx];
  return {
    row_number: slot ? slot.row_number : null,
    編號: slot ? slot['編號'] : (currentBookingCount + idx + 1),
    USERID: userId,
    名字: name
  };
}).filter(r => r.row_number !== null); // 防呆:空位不夠就不寫入超出的部分

const combinedNamesText = names.join('、');

return [{
  json: {
    canBook: true,
    targetDate: targetDate,
    sheetRows: rowsToWrite,
    replyMessage: `🎉 報名成功！\n📅 場次：${targetDate}\n👤 報名名單：${combinedNamesText}\n🔢 總人數：${requestedCount} 位`
  }
}];

// ==========================================
// 1. 取得 API 回傳的 sheets 與 spreadsheetId
// ==========================================
const firstItem = $input.first()?.json || {};
const sheets = firstItem.sheets || [];
const spreadsheetId = firstItem.spreadsheetId || '1BsJKQOugDRuxqpW2sDnFe1avARaVtxpXkDrV1WSVaHM';

// ==========================================
// 2. 取得台灣時間 (Asia/Taipei) 的今天日期 (YYYYMMDD)
// ==========================================
const todayStr = new Date().toLocaleDateString('zh-TW', {
  timeZone: 'Asia/Taipei',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).replace(/\//g, '');

const dateRegex = /^\d{8}$/;

// ==========================================
// 3. 三重過濾：符合8碼日期 + 未過期(>=今天) + 未被隱藏
// ==========================================
const validSheets = sheets
  .filter(s => {
    const title = s.properties.title || '';
    const isHidden = s.properties.hidden === true;
    return dateRegex.test(title) && title >= todayStr && !isHidden;
  })
  .map(s => s.properties.title);

// ==========================================
// 4. 無有效場次時的安全防護機制
// ==========================================
if (validSheets.length === 0) {
  return [{
    json: {
      hasSheets: false,
      spreadsheetId,
      validSheets: [],
      ranges: [],
      rangesParam: ''
    }
  }];
}

// ==========================================
// 5. 組裝下游兩分支各自需要的資料格式
// ==========================================
// 分支 B (產生開團Flex) 使用：只抓名單區 C16:C
const ranges = validSheets.map(date => `'${date}'!C16:C`);

// 分支 A (預約紀錄查詢) 使用：抓整頁 A1:C100 進行 USERID 比對
const rangesParam = validSheets.map(date => `ranges='${date}'!A1:C100`).join('&');

return [{
  json: {
    hasSheets: true,
    spreadsheetId,
    validSheets,
    ranges,        // 👈 給「查詢分頁1」節點使用
    rangesParam    // 👈 給「3. 批次讀取試算表資料」節點使用
  }
}];

const lineData = $('Line Messaging Trigger').first().json;
const targetUserId = lineData.source ? lineData.source.userId : '';
const valueRanges = $input.first().json.valueRanges || [];
const myBookings = [];

valueRanges.forEach(sheetData => {
  if (!sheetData.values || sheetData.values.length === 0) return;
  const rawRange = sheetData.range || '';
  const sheetName = rawRange.split('!')[0].replace(/'/g, '');
  const rows = sheetData.values;

  for (let i = 1; i < rows.length; i++) {
    const row = rows[i];
    if (!row || row.length === 0) continue;
    const cleanRow = row.map(cell => String(cell || '').trim());
    const hasUserId = cleanRow.includes(targetUserId);

    if (hasUserId) {
      const name = cleanRow.find(cell => cell !== targetUserId && !/^\d+$/.test(cell) && cell.length > 0) || '團員';
      myBookings.push({ date: sheetName, name: name });
    }
  }
});

if (myBookings.length === 0) {
  const emptyObj = {
    type: "bubble",
    size: "mega",
    body: {
      type: "box",
      layout: "vertical",
      contents: [
        { type: "text", text: "🏸 預約紀錄查詢", weight: "bold", size: "xl", color: "#1DB446" },
        { type: "text", text: "您目前在未來的開團場次中\n【尚無報名紀錄】喔！", margin: "md", wrap: true, color: "#666666", size: "sm" }
      ]
    }
  };
  return [{ json: { altText: "🏸 預約紀錄查詢結果", flexJsonString: JSON.stringify(emptyObj) } }];
}

const groupedBookings = {};
myBookings.forEach(item => {
  if (!groupedBookings[item.date]) groupedBookings[item.date] = [];
  groupedBookings[item.date].push(item.name);
});

const contentsList = [];
Object.keys(groupedBookings).forEach((dateStr, index) => {
  const formattedDate = `${dateStr.substring(0, 4)}/${dateStr.substring(4, 6)}/${dateStr.substring(6, 8)}`;
  const namesText = groupedBookings[dateStr].join('、');

  if (index > 0) contentsList.push({ type: "separator", margin: "lg" });

  contentsList.push({
    type: "box",
    layout: "vertical",
    margin: "lg",
    spacing: "sm",
    contents: [
      {
        type: "box",
        layout: "horizontal",
        contents: [
          { type: "text", text: "📅 場次", size: "xs", color: "#aaaaaa", flex: 2 },
          { type: "text", text: formattedDate, size: "sm", color: "#111111", flex: 5, weight: "bold" },
          { type: "text", text: "已預約", size: "xs", color: "#22C55E", flex: 2, weight: "bold", align: "end" }
        ]
      },
      {
        type: "box",
        layout: "horizontal",
        margin: "md",
        contents: [
          { type: "text", text: "👤 姓名", size: "xs", color: "#aaaaaa", flex: 2 },
          { type: "text", text: namesText, size: "sm", color: "#333333", flex: 7, wrap: true }
        ]
      },
      // 兩按鈕平排容器
      {
        type: "box",
        layout: "horizontal",
        spacing: "sm",
        margin: "md",
        contents: [
          {
            type: "button",
            action: {
              type: "postback",
              label: "📋 查看名單",
              data: `action=refresh&date=${dateStr}`, // 🟢 已修改 Postback 為 action=refresh&date
              displayText: `查看 ${formattedDate} 的報名名單`
            },
            style: "secondary",
            color: "#E2E8F0",
            height: "sm",
            flex: 1
          },
          {
            type: "button",
            action: {
              type: "postback",
              label: "❌ 取消預約",
              data: `action=cancel&date=${dateStr}`,
              displayText: `我要取消 ${formattedDate} 的預約`
            },
            style: "secondary",
            color: "#FEE2E2",
            height: "sm",
            flex: 1
          }
        ]
      }
    ]
  });
});

if (contentsList.length === 0) {
  contentsList.push({ type: "text", text: "查無資料", size: "sm", color: "#999999" });
}

const flexObj = {
  type: "bubble",
  size: "mega",
  header: {
    type: "box",
    layout: "vertical",
    backgroundColor: "#0F172A",
    paddingAll: "md",
    contents: [{ type: "text", text: "🏸 我的羽球預約紀錄", weight: "bold", color: "#38BDF8", size: "lg" }]
  },
  "body": {
    type: "box",
    layout: "vertical",
    contents: contentsList
  }
};

return [{ json: { altText: "🏸 您的羽球預約紀錄", flexJsonString: JSON.stringify(flexObj) } }];

const lineData = $('Line Messaging Trigger').first().json;
const text = lineData.message?.text || "";
const userId = lineData.source?.userId || "";
const replyToken = lineData.replyToken || "";

const match = text.trim().match(/^開團\s+(\S+)\s+(\d+)$/);

if (match) {
  return [{
    json: {
      action: "CREATE_SHEET",
      sheetName: match[1],
      maxCapacity: Number(match[2]),
      userId: userId,
      replyToken: replyToken,
      isValid: true
    }
  }];
} else {
  return [{
    json: {
      isValid: false,
      error: "格式不符，請使用：開團 [西元年00000000/日期] [人數]",
      textReceived: text,
      userId: userId,
      replyToken: replyToken
    }
  }];
}

// 1. 取得 Line Messaging Trigger 的事件資料
const triggerData = $('Line Messaging Trigger').first().json;
const targetUserId = triggerData.source ? triggerData.source.userId : '';
const postbackData = triggerData.postback ? triggerData.postback.data : '';
const replyToken = triggerData.replyToken || '';

// 2. 解析 Postback 中的 action 與 date
let action = '';
let sheetName = '';

if (postbackData && postbackData.includes('action=')) {
  const pairs = postbackData.split('&');
  pairs.forEach(pair => {
    const [key, value] = pair.split('=');
    if (key === 'action') action = value;
    if (key === 'date') sheetName = value;
  });
}

// 3. 取得上游 Google Sheets (Get Rows) 傳進來的所有列資料
const sheetRows = $input.all().map(item => item.json);

// 4. 搜尋並比對相同 USERID 的所有資料列
const matchedItems = [];
const allMatchedNames = [];

sheetRows.forEach(row => {
  if (row.USERID && String(row.USERID).trim() === targetUserId) {
    matchedItems.push({
      row_number: row.row_number,
      編號: row['編號'] || ''
    });
    if (row['名字']) {
      allMatchedNames.push(row['名字']);
    }
  }
});

// 5. 格式化日期顯示
let formattedDate = sheetName;
if (sheetName.length === 8 && !isNaN(sheetName)) {
  const y = sheetName.substring(0, 4);
  const m = sheetName.substring(4, 6);
  const d = sheetName.substring(6, 8);
  formattedDate = `${y}/${m}/${d}`;
}

// 6. 查無資料時防禦
if (matchedItems.length === 0) {
  return [{
    json: {
      found: false,
      sheetName: sheetName,
      targetUserId: targetUserId,
      replyToken: replyToken,
      replyMessage: `⚠️ 在 ${formattedDate} 的場次中未找到您的報名紀錄！`
    }
  }];
}

// 7. 將要清空的欄位顯式設為 null，確保 Google Sheets 節點清空儲存格
const namesText = allMatchedNames.join('、');

return matchedItems.map((item) => ({
  json: {
    found: true,
    sheetName: sheetName,
    row_number: item.row_number,
    編號: item.編號,
    USERID: null,            // 關鍵：給予 null 才會真正清空 USERID 儲存格
    名字: null,              // 關鍵：給予 null 才會真正清空 名字 儲存格
