    row_number: validState.row_number,   // 🟢 新增這行
    names: names,
    totalCount: names.length,
    timestamp: timestampStr,
    replyMessage: `🎉 報名成功！\n📅 場次：${targetDateRaw}\n👤 報名名單：${combinedNamesText}\n🔢 總人數：${names.length} 位`
  }
}];

// 取得這次應該要寫入的資料(來自 Code in JavaScript2)
const expectedRows = $('Code in JavaScript2').all().map(item => item.json);
const targetDate = expectedRows[0]?.sheetName;
const expectedUserId = expectedRows[0]?.USERID;

// 取得剛剛回讀的整張分頁資料
const actualRows = $input.all().map(item => item.json);

// 1. 逐筆核對:這次要寫入的每個 row_number,實際內容是否等於預期
const mismatchedRows = [];
expectedRows.forEach(expected => {
  const actual = actualRows.find(r => r.row_number === expected.row_number);
  const actualName = actual ? String(actual['名字'] || '').trim() : '';
  const actualUserId = actual ? String(actual['USERID'] || '').trim() : '';
  const expectedName = String(expected['名字'] || '').trim();

  // 若該列的 USERID 或名字跟我們寫入的不一致,代表被別人搶先覆蓋或寫入失敗
  if (actualUserId !== expectedUserId || actualName !== expectedName) {
    mismatchedRows.push({ row_number: expected.row_number, expectedName, actualName, actualUserId });
  }
});

// 2. 核對總人數是否超過上限(防止並發時兩人都通過檢查、都寫入成功、但加總超賣)
const bookedList = actualRows.filter(row => {
  const hasNumber = row['編號'] !== undefined && row['編號'] !== null && String(row['編號']).trim() !== '';
  const hasName = row['名字'] !== undefined && row['名字'] !== null && String(row['名字']).trim().length > 0;
  return hasNumber && hasName;
});

const capacityRow = actualRows.find(r => r['標題'] === '人數');
const maxCapacity = capacityRow ? Number(capacityRow['內容']) || 16 : 16;
const currentCount = bookedList.length;
const isOverCapacity = currentCount > maxCapacity;

const verified = mismatchedRows.length === 0 && !isOverCapacity;

return [{
  json: {
    verified,
    mismatchedRows,
    isOverCapacity,
    currentCount,
    maxCapacity,
    targetDate,
    expectedUserId,
    expectedRows,
    failReason: !verified
      ? (isOverCapacity ? '名額已滿,您的報名未成功寫入' : '寫入時發生衝突,可能與其他人同時搶名額')
      : ''
  }
}];

const data = $input.first().json;
return data.expectedRows.map(row => ({
  json: {
    row_number: row.row_number,
    USERID: null,
    名字: null,
    sheetName: data.targetDate,
    failReason: data.failReason
  }
}));

