} else if (input.events && input.events.length > 0) {
  event = input.events[0];
} else if (input.type && input.source) {
  event = input;
}

function parseQueryString(qs) {
  const params = {};
  if (!qs) return params;
  const pairs = qs.split('&');
  for (const pair of pairs) {
    const [key, val] = pair.split('=');
    if (key) {
      params[decodeURIComponent(key)] = val ? decodeURIComponent(val) : '';
    }
  }
  return params;
}

if (event) {
  const userId = event.source?.userId || '';
  const replyToken = event.replyToken || '';

  // 1. 文字訊息處理
  if (event.type === 'message' && event.message?.type === 'text') {
    const text = event.message.text.trim();

    // 觸發：新增教學 / 教學 / 說明 / 幫助
    if (['新增教學', '教學', '說明', '幫助'].includes(text)) {
      return [{
        json: {
          route: 'add_help',
          userId,
          replyToken
        }
      }];
    } 
    // 觸發：變更 / 修改
    else if (text.startsWith('變更') || text.startsWith('修改')) {
      const parts = text.split(/\s+/);
      const taskName = parts[1] || '';
      const cycleDays = parseInt(parts[2], 10) || 7;

      return [{
        json: {
          route: 'change_cycle',
          userId,
          replyToken,
          taskName,
          cycleDays
        }
      }];
    } 
    // 觸發：新增
    else if (text.startsWith('新增')) {
      const parts = text.split(/\s+/);
      const taskName = parts[1] || '未命名事項';
      const cycleDays = parseInt(parts[2], 10) || 7;

      return [{
        json: {
          route: 'add_preview',
          userId,
          replyToken,
          taskName,
          cycleDays
        }
      }];
    } 
    // 觸發：查詢 / 待辦 / 清單
    else if (['查詢', '待辦', '清單'].includes(text)) {
      return [{
        json: {
          route: 'query_list',
          userId,
          replyToken,
          page: 1
        }
      }];
    }
  } 

  // 2. Postback 按鈕事件處理
  else if (event.type === 'postback') {
    const params = parseQueryString(event.postback?.data || '');
    const action = params.action || '';
    const taskId = params.task_id || '';
    const taskName = params.task || '';
    const cycleDays = parseInt(params.cycle || '7', 10);
    const page = parseInt(params.page || '1', 10);

    return [{
      json: {
        route: 'postback',
        action,
        taskId,
        taskName,
        cycleDays,
        page,
        userId,
        replyToken
      }
    }];
  }
}

return [{ json: { route: 'unknown' } }];

const data = $input.first().json;
