  const dateB = b.next_execution ? new Date(b.next_execution).getTime() : Infinity;
  return dateA - dateB;
});

// 3. 每 3 個一組切割卡片
const chunkSize = 3;
const taskGroups = [];
for (let i = 0; i < tasks.length; i += chunkSize) {
  taskGroups.push(tasks.slice(i, i + chunkSize));
}

const todayMs = new Date().setHours(0, 0, 0, 0);

const bubbles = taskGroups.map((group, groupIdx) => {
  const cardPage = groupIdx + 1;
  const cardContents = [
    {
