        statusText = `⚠️ 剩 ${diffDays} 天`;
        statusBgColor = '#FFF5E5';
        statusColor = '#D97706';
      } else {
        statusText = `⏳ 剩 ${diffDays} 天`;
        statusBgColor = '#E6F9ED';
        statusColor = '#06C755';
      }
    }

    cardContents.push({
      type: 'box',
      layout: 'vertical',
      spacing: 'xs',
      margin: 'md',
      contents: [
