  }
}];

// 取得這次應該要寫入的資料(來自 Code in JavaScript2)
const expectedRows = $('Code in JavaScript2').all().map(item => item.json);
const targetDate = expectedRows[0]?.sheetName;
const expectedUserId = expectedRows[0]?.USERID;

// 取得剛剛回讀的整張分頁資料
const actualRows = $input.all().map(item => item.json);

// 1. 逐筆核對:這次要寫入的每個 row_number,實際內容是否等於預期
const mismatchedRows = [];
expectedRows.forEach(expected => {
  const actual = actualRows.find(r => r.row_number === expected.row_number);
  const actualName = actual ? String(actual['名字'] || '').trim() : '';
  const actualUserId = actual ? String(actual['USERID'] || '').trim() : '';
  const expectedName = String(expected['名字'] || '').trim();

  // 若該列的 USERID 或名字跟我們寫入的不一致,代表被別人搶先覆蓋或寫入失敗
  if (actualUserId !== expectedUserId || actualName !== expectedName) {
    mismatchedRows.push({ row_number: expected.row_number, expectedName, actualName, actualUserId });
  }
});

// 2. 核對總人數是否超過上限(防止並發時兩人都通過檢查、都寫入成功、但加總超賣)
const bookedList = actualRows.filter(row => {
