  const hasName = row['名字'] !== undefined && row['名字'] !== null && String(row['名字']).trim().length > 0;
  return hasNumber && hasName;
});

const capacityRow = actualRows.find(r => r['標題'] === '人數');
const maxCapacity = capacityRow ? Number(capacityRow['內容']) || 16 : 16;
const currentCount = bookedList.length;
const isOverCapacity = currentCount > maxCapacity;

const verified = mismatchedRows.length === 0 && !isOverCapacity;

return [{
  json: {
    verified,
    mismatchedRows,
    isOverCapacity,
    currentCount,
    maxCapacity,
    targetDate,
    expectedUserId,
    expectedRows,
    failReason: !verified
      ? (isOverCapacity ? '名額已滿,您的報名未成功寫入' : '寫入時發生衝突,可能與其他人同時搶名額')
      : ''
  }
}];

const data = $input.first().json;
return data.expectedRows.map(row => ({
  json: {
    row_number: row.row_number,
    USERID: null,
    名字: null,
    sheetName: data.targetDate,
    failReason: data.failReason
  }
}));

