const data = $input.first().json;

let finalFlexJson;

if (data.flexMessage) {
  // 有現成的 Flex 卡片(例如超賣情境),直接沿用
  finalFlexJson = data.flexMessage;
} else {
  // 沒有現成卡片(例如逾時情境),用簡單的 bubble 包裝文字訊息
  const fallbackText = data.replyMessage || '⚠️ 報名發生異常，請重新點選「刷新頁面」後再試一次。';

  const flexFallback = {
    type: 'bubble',
    size: 'mega',
    header: {
      type: 'box',
      layout: 'vertical',
      backgroundColor: '#95A5A6',
      paddingAll: 'xl',
      contents: [
        { type: 'text', text: '⚠️ 系統通知', weight: 'bold', color: '#FFFFFF', size: 'lg' }
      ]
    },
    body: {
      type: 'box',
      layout: 'vertical',
      paddingAll: 'xl',
      contents: [
        { type: 'text', text: fallbackText, size: 'md', color: '#333333', wrap: true }
      ]
    }
  };

  finalFlexJson = JSON.stringify(flexFallback);
}

return [{ json: { ...data, finalFlexJson } }];

const items = $input.all();
const todayStr = new Date().toISOString().split('T')[0];
const today = new Date(todayStr);
const dueTasks = [];

for (const item of items) {
  const task = item.json;
  if (task.status === 'active' && task.next_execution && task.next_execution <= todayStr) {
    const cycle = parseInt(task.cycle_days || '7', 10);
    const nextDate = new Date(today);
    nextDate.setDate(today.getDate() + cycle);
    const nextExecStr = nextDate.toISOString().split('T')[0];
    dueTasks.push({
      json: {
        task_id: task.task_id,
        user_id: task.user_id,
        task_name: task.task_name,
        cycle_days: cycle,
        last_executed: todayStr,
        next_execution: nextExecStr,
        push_body: {
          to: task.user_id,
          messages: [
            {
              type: 'text',
              text: `⏰ 提醒：【${task.task_name}】今天到期囉！（週期：${cycle} 天）`
            }
          ]
        }
      }
    });
  }
}
return dueTasks;

const input = $input.first().json;

let event = null;
if (input.body && input.body.events && input.body.events.length > 0) {
  event = input.body.events[0];
} else if (input.events && input.events.length > 0) {
  event = input.events[0];
} else if (input.type && input.source) {
  event = input;
}

function parseQueryString(qs) {
  const params = {};
  if (!qs) return params;
  const pairs = qs.split('&');
  for (const pair of pairs) {
    const [key, val] = pair.split('=');
    if (key) {
      params[decodeURIComponent(key)] = val ? decodeURIComponent(val) : '';
    }
  }
  return params;
}

if (event) {
  const userId = event.source?.userId || '';
  const replyToken = event.replyToken || '';

  // 1. 文字訊息處理
  if (event.type === 'message' && event.message?.type === 'text') {
    const text = event.message.text.trim();

    // 觸發：新增教學 / 教學 / 說明 / 幫助
    if (['新增教學', '教學', '說明', '幫助'].includes(text)) {
      return [{
        json: {
          route: 'add_help',
          userId,
          replyToken
        }
      }];
    } 
    // 觸發：變更 / 修改
    else if (text.startsWith('變更') || text.startsWith('修改')) {
      const parts = text.split(/\s+/);
      const taskName = parts[1] || '';
      const cycleDays = parseInt(parts[2], 10) || 7;

      return [{
        json: {
          route: 'change_cycle',
          userId,
          replyToken,
          taskName,
          cycleDays
        }
      }];
    } 
    // 觸發：新增
    else if (text.startsWith('新增')) {
      const parts = text.split(/\s+/);
      const taskName = parts[1] || '未命名事項';
      const cycleDays = parseInt(parts[2], 10) || 7;

      return [{
        json: {
          route: 'add_preview',
          userId,
          replyToken,
          taskName,
          cycleDays
        }
      }];
    } 
    // 觸發：查詢 / 待辦 / 清單
    else if (['查詢', '待辦', '清單'].includes(text)) {
      return [{
        json: {
          route: 'query_list',
          userId,
          replyToken,
          page: 1
        }
      }];
    }
  } 

  // 2. Postback 按鈕事件處理
  else if (event.type === 'postback') {
    const params = parseQueryString(event.postback?.data || '');
    const action = params.action || '';
    const taskId = params.task_id || '';
    const taskName = params.task || '';
    const cycleDays = parseInt(params.cycle || '7', 10);
    const page = parseInt(params.page || '1', 10);

    return [{
      json: {
        route: 'postback',
        action,
        taskId,
        taskName,
        cycleDays,
        page,
        userId,
        replyToken
      }
    }];
  }
}

return [{ json: { route: 'unknown' } }];

const data = $input.first().json;
const taskId = `TASK_${Date.now()}`;

const flexBubble = {
  type: 'bubble',
  header: { type: 'box', layout: 'vertical', contents: [{ type: 'text', text: '🔔 新增待辦事項確認', weight: 'bold', size: 'md', color: '#1DB446' }] },
  body: {
    type: 'box',
    layout: 'vertical',
    spacing: 'md',
    contents: [
      { type: 'text', text: `事項：${data.taskName}`, weight: 'bold', size: 'xl' },
      { type: 'text', text: `週期：${data.cycleDays} 天`, size: 'lg', color: '#666666' }
    ]
  },
  footer: {
    type: 'box',
    layout: 'vertical',
    contents: [
      {
        type: 'button',
        style: 'primary',
        color: '#06C755',
        action: {
          type: 'postback',
          label: '確認建立並記錄',
          data: `action=confirm_add&task_id=${taskId}&task=${encodeURIComponent(data.taskName)}&cycle=${data.cycleDays}`,
          displayText: `確認建立【${data.taskName}】`
        }
      }
    ]
  }
};

return [{
  json: {
    replyToken: data.replyToken,
    altText: '請確認待辦事項建立',
    flexJson: JSON.stringify(flexBubble)
  }
}];

const items = $input.all();
const routeData = $('路由判斷與解析').first().json;
const currentPage = routeData.page || 1;

// 1. 過濾屬於該用戶且 active 的事項
let tasks = items.map(i => i.json).filter(t => t.status === 'active' && t.user_id === routeData.userId);

if (tasks.length === 0) {
  return [{
    json: {
      replyToken: routeData.replyToken,
      altText: '目前沒有待辦事項',
      flexJson: JSON.stringify({
        type: 'bubble',
        body: {
          type: 'box',
          layout: 'vertical',
          spacing: 'md',
          contents: [
            { type: 'text', text: '🎉', size: '3xl', align: 'center' },
            { type: 'text', text: '目前沒有任何進行中的待辦事項！', size: 'lg', weight: 'bold', align: 'center', color: '#1DB446' }
          ]
        }
      })
    }
  }];
}

// 2. 排序：下次執行日（next_execution）越早/越快到的排在最上面
tasks.sort((a, b) => {
  const dateA = a.next_execution ? new Date(a.next_execution).getTime() : Infinity;
  const dateB = b.next_execution ? new Date(b.next_execution).getTime() : Infinity;
  return dateA - dateB;
});

// 3. 每 3 個一組切割卡片
const chunkSize = 3;
const taskGroups = [];
for (let i = 0; i < tasks.length; i += chunkSize) {
  taskGroups.push(tasks.slice(i, i + chunkSize));
}

const todayMs = new Date().setHours(0, 0, 0, 0);

const bubbles = taskGroups.map((group, groupIdx) => {
  const cardPage = groupIdx + 1;
  const cardContents = [
    {
      type: 'box',
      layout: 'horizontal',
      alignItems: 'center',
      contents: [
        { type: 'text', text: '📋 待辦事項清單', weight: 'bold', size: 'md', color: '#1DB446', flex: 1 },
        { type: 'text', text: `第 ${cardPage}/${taskGroups.length} 頁`, size: 'xs', color: '#aaaaaa', align: 'end' }
      ]
    },
    { type: 'separator', margin: 'sm' }
  ];

  group.forEach((data, itemIdx) => {
    const taskNumber = (cardPage - 1) * chunkSize + itemIdx + 1;

    // 計算剩餘天數與動態標籤顏色
    let statusText = '⏰ 未設定';
    let statusBgColor = '#eeeeee';
    let statusColor = '#666666';

    if (data.next_execution) {
      const nextMs = new Date(data.next_execution).setHours(0, 0, 0, 0);
      const diffDays = Math.ceil((nextMs - todayMs) / (1000 * 60 * 60 * 24));

      if (diffDays < 0) {
        statusText = `🚨 已逾期 ${Math.abs(diffDays)} 天`;
        statusBgColor = '#FFE5E5';
        statusColor = '#DE2626';
      } else if (diffDays === 0) {
        statusText = '🔥 今天到期';
        statusBgColor = '#FFE5E5';
        statusColor = '#DE2626';
      } else if (diffDays <= 3) {
        statusText = `⚠️ 剩 ${diffDays} 天`;
        statusBgColor = '#FFF5E5';
        statusColor = '#D97706';
      } else {
        statusText = `⏳ 剩 ${diffDays} 天`;
        statusBgColor = '#E6F9ED';
        statusColor = '#06C755';
      }
    }

    cardContents.push({
      type: 'box',
      layout: 'vertical',
      spacing: 'xs',
      margin: 'md',
      contents: [
        {
          type: 'box',
          layout: 'horizontal',
          alignItems: 'center',
          spacing: 'sm',
          contents: [
            { type: 'text', text: `${taskNumber}. ${data.task_name}`, weight: 'bold', size: 'xl', wrap: true, flex: 2, color: '#111111' },
            {
              type: 'box',
              layout: 'vertical',
              backgroundColor: statusBgColor,
              cornerRadius: 'md',
              paddingAll: 'xs',
              paddingStart: 'sm',
              paddingEnd: 'sm',
              flex: 0,
              contents: [
                { type: 'text', text: statusText, size: 'xs', color: statusColor, weight: 'bold', align: 'center' }
              ]
            }
          ]
        },
        {
          type: 'box',
          layout: 'vertical',
          spacing: 'xs',
          margin: 'sm',
          contents: [
            { type: 'text', text: `🔄 週期：${data.cycle_days} 天`, size: 'md', color: '#555555' },
            { type: 'text', text: `🗓️ 上次：${data.last_executed || '尚未記錄'}`, size: 'md', color: '#555555' },
            { type: 'text', text: `🎯 下次：${data.next_execution || '未設定'}`, size: 'md', color: '#111111', weight: 'bold' }
          ]
        },
        {
          type: 'box',
          layout: 'horizontal',
          spacing: 'md',
          margin: 'md',
          contents: [
            {
              type: 'box',
              layout: 'vertical',
              backgroundColor: '#E6F9ED',
              cornerRadius: 'md',
              paddingAll: 'sm',
              action: {
                type: 'postback',
                data: `action=execute_today&task_id=${data.task_id}&cycle=${data.cycle_days}&page=${cardPage}`,
                displayText: `完成【${data.task_name}】`
              },
              contents: [
                { type: 'text', text: '✅ 今日已執行', size: 'md', color: '#06C755', weight: 'bold', align: 'center' }
              ]
            },
            {
              type: 'box',
              layout: 'vertical',
              backgroundColor: '#FFE5E5',
              cornerRadius: 'md',
              paddingAll: 'sm',
              action: {
                type: 'postback',
                data: `action=delete_task&task_id=${data.task_id}&page=${cardPage}`,
                displayText: `刪除【${data.task_name}】`
              },
              contents: [
                { type: 'text', text: '🗑️ 刪除', size: 'md', color: '#DE2626', weight: 'bold', align: 'center' }
              ]
            }
          ]
        }
      ]
    });

    if (itemIdx < group.length - 1) cardContents.push({ type: 'separator', margin: 'md' });
  });

  return { type: 'bubble', body: { type: 'box', layout: 'vertical', spacing: 'md', contents: cardContents } };
});

return [{
  json: {
    replyToken: routeData.replyToken,
    altText: '最新待辦事項清單',
    flexJson: JSON.stringify({ type: 'carousel', contents: bubbles })
  }
}];

const data = $input.first().json;

const flexBubble = {
  type: 'bubble',
  header: {
    type: 'box',
    layout: 'vertical',
    contents: [
      { type: 'text', text: '💡 待辦機器人使用教學', weight: 'bold', size: 'md', color: '#1DB446' }
    ]
  },
  body: {
    type: 'box',
    layout: 'vertical',
    spacing: 'md',
    contents: [
      { type: 'text', text: '➕ 新增待辦事項', weight: 'bold', size: 'md', color: '#111111' },
      { type: 'text', text: '格式：新增 [事項] [天數]', size: 'xs', color: '#555555' },
      { type: 'text', text: '• 範例：新增 換床單 30\n• 範例：新增 澆花 3', size: 'xs', color: '#888888', wrap: true },
      { type: 'separator', margin: 'sm' },
      { type: 'text', text: '🔄 變更提醒週期', weight: 'bold', size: 'md', color: '#111111' },
      { type: 'text', text: '格式：變更 [事項] [新天數] （也可寫「修改」）', size: 'xs', color: '#555555' },
      { type: 'text', text: '• 範例：變更 換床單 14\n• 範例：修改 澆花 5', size: 'xs', color: '#888888', wrap: true },
      { type: 'separator', margin: 'sm' },
      { type: 'text', text: '📋 查詢與管理清單', weight: 'bold', size: 'md', color: '#111111' },
      { type: 'text', text: '輸入「查詢」、「待辦」或「清單」，即可發送最新待辦卡片，並可直接點擊按鈕標記已執行或刪除。', size: 'xs', color: '#555555', wrap: true }
    ]
  },
  footer: {
    type: 'box',
    layout: 'vertical',
    spacing: 'sm',
    contents: [
      {
        type: 'button',
        style: 'secondary',
        color: '#F0F0F0',
        action: {
          type: 'message',
          label: '複製新增範例：新增 換床單 30',
          text: '新增 換床單 30'
        }
      },
      {
        type: 'button',
        style: 'secondary',
        color: '#F0F0F0',
        action: {
          type: 'message',
          label: '複製變更範例：變更 換床單 14',
          text: '變更 換床單 14'
        }
      }
    ]
  }
};

return [{
  json: {
    replyToken: data.replyToken,
    altText: '待辦事項使用教學',
    flexJson: JSON.stringify(flexBubble)
  }
}];

const items = $input.all().map(i => i.json);
const routeData = $('路由判斷與解析').first().json;

// 嚴格過濾：必須是 active 且名稱符合的事項
const target = items.find(t => t.status === 'active' && t.task_name === routeData.taskName);

if (!target) {
  return [{
    json: {
      found: false,
      replyToken: routeData.replyToken
    }
  }];
}

return [{
  json: {
    found: true,
    taskId: target.task_id,
    taskName: target.task_name,
    cycleDays: routeData.cycleDays,
    userId: routeData.userId,
    replyToken: routeData.replyToken
  }
}];

const items = $input.all().map(i => i.json);
const routeData = $('路由判斷與解析').first().json;

// 檢查是否有同名且 active 的事項
const exists = items.some(t => t.status === 'active' && t.task_name === routeData.taskName);

if (exists) {
  return [{
    json: {
      isDuplicate: true,
      replyToken: routeData.replyToken,
      altText: `⚠️ 事項【${routeData.taskName}】已存在`,
      flexJson: JSON.stringify({
        type: 'bubble',
        body: {
          type: 'box',
          layout: 'vertical',
          spacing: 'md',
          contents: [
            { type: 'text', text: '⚠️ 事項已存在', weight: 'bold', size: 'lg', color: '#DE2626' },
            { type: 'text', text: `系統中已有進行中的【${routeData.taskName}】！`, size: 'sm', color: '#555555', wrap: true },
            { type: 'text', text: `建議處理方式：\n1. 修改週期：輸入「變更 ${routeData.taskName} ${routeData.cycleDays}」\n2. 區分名稱重新新增：如「${routeData.taskName}-主臥」`, size: 'xs', color: '#888888', wrap: true }
          ]
        }
      })
    }
  }];
}

return [{
  json: {
    isDuplicate: false,
    ...routeData
  }
}];
